const rows = $input.all().map(i => i.json);

const threads = {};
for (const row of rows) {
  const id = row.threadId;
  if (!id) continue;

  if (!threads[id]) {
    threads[id] = {
      threadId: id,
      channel: row.channel,
      priority: row.priority || 'normal',
      escalated: false,
      rows: []
    };
  }
  if (String(row.isEscalated).toLowerCase() === 'true') threads[id].escalated = true;
  threads[id].rows.push(row);
}

const cases = [];
for (const thread of Object.values(threads)) {
  if (!thread.escalated) continue;

  const sorted = thread.rows.sort((a, b) =>
    new Date(a.timestampReceived || a.timestampStart || 0) -
    new Date(b.timestampReceived || b.timestampStart || 0)
  );

  const hasResolution = sorted.some(r =>
    r.response && r.response !== 'Pending' && r.response !== 'None'
  );
  if (!hasResolution) continue;

  const queries = sorted
    .filter(r => r.query && r.query !== 'None')
    .map(r => r.query.trim())
    .join(' | ');

  const resolutions = sorted
    .filter(r => r.response && r.response !== 'Pending' && r.response !== 'None')
    .map(r => r.response.trim())
    .join(' | ');

  const date = sorted[0].timestampReceived || sorted[0].timestampStart || 'Unknown';

  cases.push({
    threadId: thread.threadId,
    date,
    priority: thread.priority,
    query: queries,
    resolution: resolutions
  });
}

return [{
  json: {
    caseCount: cases.length,
    cases
  }
}];

const input = $input.first().json;
const cases = input.cases || [];

const formatted = cases.map((c, idx) =>
  `--- RAW CASE ${idx + 1} ---\nthreadId: ${c.threadId}\ndate: ${c.date}\npriority: ${c.priority}\ncustomer_query: ${c.query}\nhuman_resolution: ${c.resolution}`
).join('\n\n');

const chatInput = `You will receive ${cases.length} resolved customer support cases below. Process them according to the rules in your system instructions and return the consolidated cases as structured JSON.\n\n${formatted}`;

return [{
  json: {
    chatInput,
    rawCases: cases
  }
}];

