const input = $input.first().json;
const out = input.output || input;
const casesToAdd = Array.isArray(out.cases) ? out.cases : [];

if (casesToAdd.length === 0) {
  return [{
    json: {
      content: 'No cases to add.',
      caseCount: 0,
      threadIds: [],
      hasContent: false,
      fileName: 'Human_Cases.txt'
    }
  }];
}

let content = '=== HUMAN CASES KNOWLEDGE BASE ===\n';
content += 'Generated: ' + new Date().toISOString() + '\n';
content += 'Total cases: ' + casesToAdd.length + '\n\n';

const allThreadIds = [];
casesToAdd.forEach((c, idx) => {
  content += `=== Case #${idx + 1} ===\n`;
  content += 'Issue: ' + (c.query || '') + '\n';
  content += 'Resolution: ' + (c.resolution || '') + '\n';
  content += '---\n\n';
  const merged = Array.isArray(c.mergedThreadIds) && c.mergedThreadIds.length > 0
    ? c.mergedThreadIds
    : (c.threadId ? [c.threadId] : []);
  merged.forEach(tid => allThreadIds.push(tid));
});

return [{
  json: {
    content,
    caseCount: casesToAdd.length,
    threadIds: allThreadIds,
    hasContent: true,
    fileName: 'Human_Cases.txt'
  }
}];
